insert into public.spark_subject_sections(subject_id,section_id,title,description,sort_order,enabled,metadata)
values
('english-a','module-1','Module 1: Informative Discourse','Read, interpret and create clear factual communication in written, spoken and visual forms.',100,true,'{"syllabus":"CXC 01/G/SYLL 25"}'::jsonb),
('english-a','module-2','Module 2: Literary Discourse','Interpret literary language, writer’s craft, character, theme, form, structure and context.',200,true,'{"syllabus":"CXC 01/G/SYLL 25"}'::jsonb),
('english-a','module-3','Module 3: Persuasive Discourse','Analyse and create reasoned persuasion across written, oral and visual forms.',300,true,'{"syllabus":"CXC 01/G/SYLL 25"}'::jsonb)
on conflict(subject_id,section_id) do update set
 title=excluded.title,description=excluded.description,sort_order=excluded.sort_order,
 enabled=excluded.enabled,metadata=excluded.metadata,updated_at=now();

do $body$
declare
  v_topics jsonb := $json$[{"id":"1.1-word-choice-grammar-meaning","section":"module-1","order":101,"title":"1.1 Word Choice, Grammar and Meaning","objectives":["Explain how word choice and grammar shape meaning in informative texts.","Recognise formal, informal, Standard English, Creole, literal and figurative choices in context."],"intro":"Informative writing works best when the reader can understand the message without guessing. This lesson focuses on how vocabulary and sentence structure change meaning, level of formality and precision.","sections":[{"title":"Word choice and context","paragraphs":["A word can be correct in one situation and unsuitable in another. A report to a principal normally needs more formal wording than a message to a friend. CSEC questions often ask which word best fits the purpose, audience and context."],"bullets":["Denotation is the direct dictionary meaning of a word.","Connotation is the feeling or association carried by a word.","Synonyms are similar in meaning, but they are not always interchangeable.","Caribbean Creoles have valid social and cultural roles, while Standard English is expected in many formal examination responses."]},{"title":"Grammar carries meaning","paragraphs":["Grammar is not only about avoiding errors. Word order, verb form, pronoun reference and agreement help the reader work out exactly who did what, when it happened and how ideas are connected."],"bullets":["Check subject-verb agreement.","Keep pronoun references clear.","Keep verb tense consistent unless the time changes.","Use sentence structure that suits the amount and importance of information."]},{"title":"Exam approach","paragraphs":["Read the whole sentence before choosing an answer. A familiar word may be wrong because of tone, grammar or context. Replace each option in the sentence and ask which one communicates the intended meaning most clearly."]}],"keyPoints":["Choose vocabulary for purpose, audience and context.","Grammar helps make relationships between ideas clear.","Similar words can carry different shades of meaning.","Standard English is normally expected in formal CSEC responses.","Always judge an option in the full sentence, not by itself."],"summary":"Precise informative language depends on suitable vocabulary and grammar working together.","cards":[{"front":"What is denotation?","back":"A word’s direct or dictionary meaning."},{"front":"What is connotation?","back":"The feelings or associations a word suggests."},{"front":"Why does audience affect diction?","back":"Different audiences require different levels of formality and word choice."},{"front":"What is subject-verb agreement?","back":"The verb must match its subject in number and person."},{"front":"Best way to test a word-choice option?","back":"Read it in the full sentence and check meaning, tone and grammar."}]},{"id":"1.2-punctuation-paragraphing","section":"module-1","order":102,"title":"1.2 Punctuation, Paragraphing and Effective Language","objectives":["Explain how punctuation and paragraphing affect meaning.","Identify effective use of parts of speech, word combinations and unusual turns of phrase."],"intro":"Punctuation and paragraphing guide the reader through information. They show where ideas begin and end, which details belong together and what should receive emphasis.","sections":[{"title":"Punctuation with purpose","paragraphs":["A punctuation mark should clarify meaning. Commas separate items or clauses, colons introduce explanations or lists, semi-colons link closely related independent clauses, and apostrophes show possession or missing letters."],"bullets":["A full stop closes a complete statement.","A colon often introduces an explanation, example or list.","A semi-colon can join closely related complete ideas.","Quotation marks identify direct speech or quoted material.","A hyphen joins some compound words; a dash can create a stronger break or emphasis."]},{"title":"Paragraphing","paragraphs":["A paragraph develops one main idea. Topic sentences signal the focus, supporting sentences develop it and transitions help the reader follow the movement from one idea to the next."],"bullets":["Start a new paragraph when the focus changes.","Keep supporting details relevant to the paragraph’s main idea.","Use transitions such as however, therefore, in addition and as a result when they genuinely fit."]},{"title":"Effective combinations","paragraphs":["Writers sometimes choose vivid verbs, precise adjectives or memorable word combinations to make even factual writing more engaging. The key question is whether the choice improves clarity and effect rather than merely sounding impressive."]}],"keyPoints":["Punctuation should make meaning easier to follow.","Paragraphs organise related ideas.","Topic sentences establish a paragraph’s main focus.","Transitions show relationships between ideas.","Effective language is precise, not unnecessarily complicated."],"summary":"Good punctuation and paragraphing make information clear, ordered and easy to read.","cards":[{"front":"Main job of a topic sentence?","back":"To state or signal the paragraph’s main idea."},{"front":"When is a colon commonly used?","back":"Before an explanation, example or list."},{"front":"What can a semi-colon join?","back":"Two closely related independent clauses."},{"front":"Why use transitions?","back":"To show how ideas are related and guide the reader."},{"front":"When should a new paragraph begin?","back":"When the focus, stage or speaker changes."}]},{"id":"1.3-facts-opinions-implications","section":"module-1","order":103,"title":"1.3 Facts, Opinions and Implied Information","objectives":["Identify explicitly stated facts and opinions.","Extract information that is implied rather than directly stated."],"intro":"English A requires you to understand both what a text says directly and what it suggests. Strong readers separate verifiable information from personal judgement and support inferences with evidence.","sections":[{"title":"Facts and opinions","paragraphs":["A factual statement can be checked against evidence. An opinion expresses a belief, judgement or preference. A statement can sound confident and still be an opinion."],"bullets":["Facts are verifiable in principle.","Opinions often contain value judgements such as best, unfair or beautiful.","Statistics may support an argument, but the interpretation of the statistics can still be opinion."]},{"title":"Reading between the lines","paragraphs":["Implied information is not stated word for word. You infer it by combining clues in the text with logical reasoning. A valid inference must be supported by the stimulus, not by personal assumptions."],"bullets":["Look for behaviour, word choice, contrast and omitted details.","Ask what the writer expects the reader to understand without saying directly.","Reject options that go beyond the evidence."]},{"title":"CSEC trap to avoid","paragraphs":["Do not confuse a possible interpretation with the best-supported interpretation. The correct answer usually has clear textual evidence even when the idea itself is implied."]}],"keyPoints":["Facts can be verified.","Opinions express judgement or belief.","Inference uses evidence plus reasoning.","Implied does not mean invented.","Choose the inference best supported by the text."],"summary":"Separate what is stated from what is inferred, and make every inference evidence-based.","cards":[{"front":"How is a fact different from an opinion?","back":"A fact can be verified; an opinion expresses judgement or belief."},{"front":"What is implied information?","back":"Meaning suggested by the text rather than stated directly."},{"front":"What makes an inference valid?","back":"It is logically supported by evidence in the stimulus."},{"front":"Can a statistic appear in an opinion?","back":"Yes. Facts may be used to support an opinion."},{"front":"Big inference mistake to avoid?","back":"Choosing an idea that is possible but not supported by the text."}]},{"id":"1.4-sequence-specific-information","section":"module-1","order":104,"title":"1.4 Sequence and Extracting Specific Information","objectives":["Identify stated or implied time sequence.","Extract specific information from written, spoken and visual material."],"intro":"Many English A questions test whether you can locate the exact detail needed and understand the order in which events or steps occur.","sections":[{"title":"Tracking sequence","paragraphs":["Sequence may be signalled by words such as first, later, meanwhile and finally, but writers do not always give events in perfect order. Dates, verb tenses and cause-effect clues can also reveal sequence."],"bullets":["Chronological order follows time.","Process order follows steps needed to complete a task.","A flashback interrupts present-time sequence to show an earlier event."]},{"title":"Finding specific information","paragraphs":["Read the question first and identify the detail being requested. Then scan for names, numbers, dates, repeated terms or synonyms connected to that detail."],"bullets":["Use headings and topic sentences to narrow the search.","Do not choose a true statement unless it answers the exact question.","In a table or chart, check labels and units before reading the figures."]},{"title":"Paraphrase awareness","paragraphs":["The question may restate the passage in different words. Train yourself to recognise equivalent meaning rather than waiting for an exact phrase match."]}],"keyPoints":["Sequence can be explicit or implied.","Time words, tense and dates are useful clues.","Scan strategically for requested details.","Read labels and units in visuals.","Expect paraphrased wording in questions."],"summary":"Accurate retrieval depends on knowing exactly what to find and how the text or visual organises it.","cards":[{"front":"What is chronological order?","back":"Events arranged according to time."},{"front":"What is a flashback?","back":"A shift from the present action to an earlier event."},{"front":"Best first step for a detail question?","back":"Identify exactly what information the question asks for."},{"front":"Why check chart units?","back":"The same number can mean different things depending on the unit."},{"front":"Why recognise paraphrase?","back":"Questions often restate a passage’s idea using different words."}]},{"id":"1.5-cause-effect-text-structures","section":"module-1","order":105,"title":"1.5 Cause and Effect and Text Structures","objectives":["Recognise cause-and-effect relationships.","Recognise common informative text structures."],"intro":"Writers organise information in predictable ways. Recognising the structure helps you locate main ideas, follow reasoning and anticipate what may come next.","sections":[{"title":"Cause and effect","paragraphs":["A cause helps produce an effect. Be careful not to assume that because two events happened together, one caused the other. Good reasoning looks for evidence of a real connection."],"bullets":["Cause asks why something happened.","Effect asks what happened as a result.","Correlation or coincidence is not automatically causation."]},{"title":"Common structures","paragraphs":["The revised syllabus highlights several structures used in informative discourse."],"bullets":["Cause and effect: explains reasons and results.","Process or chronology: explains steps or time order.","Description: presents features or characteristics.","Problem and solution: identifies a difficulty and responses.","Compare and contrast: shows similarities and differences.","Classification: groups items by shared features.","Definition: explains the meaning or nature of a concept."]},{"title":"How to identify structure","paragraphs":["Focus on the relationship among ideas, not one signal word. A paragraph may use 'because' once but still be mainly a comparison or description."]}],"keyPoints":["Cause is different from coincidence.","Text structure describes how ideas are organised.","One passage can contain more than one structure.","Choose the dominant structure when asked for the main one.","Structure helps predict where information will appear."],"summary":"Recognising cause-effect and organisational patterns makes comprehension faster and more accurate.","cards":[{"front":"Cause versus effect?","back":"Cause explains why; effect is the result."},{"front":"What is problem-solution structure?","back":"It presents a difficulty and one or more ways to address it."},{"front":"What does compare-contrast do?","back":"Shows similarities and differences."},{"front":"What does classification do?","back":"Groups items according to shared features."},{"front":"Why not rely on one signal word?","back":"The dominant relationship among ideas determines the structure."}]},{"id":"1.6-purpose-audience-informative","section":"module-1","order":106,"title":"1.6 Purpose, Audience and Informative Discourse","objectives":["Distinguish informative discourse from literary and persuasive discourse.","Identify a writer’s precise purpose and intended audience."],"intro":"Purpose answers why a text was created. Audience answers who it was created for. Both influence vocabulary, tone, detail and structure.","sections":[{"title":"Three broad purposes","paragraphs":["Informative discourse primarily explains or informs. Literary discourse often explores experience and creates emotional or imaginative effects. Persuasive discourse aims to influence belief or action. Real texts can mix purposes, so identify the dominant one."],"bullets":["Informative: explain, report, instruct, clarify.","Literary: entertain, explore, evoke, imagine.","Persuasive: convince, motivate, recommend, challenge."]},{"title":"Audience clues","paragraphs":["Technical vocabulary may suggest a specialist audience, while definitions and examples may indicate a general audience. Tone, assumed knowledge, examples and the form of the text are useful clues."],"bullets":["Ask what the writer assumes the reader already knows.","Notice whether the writer gives background explanations.","Look at where the text might realistically appear."]},{"title":"Precise purpose","paragraphs":["Instead of answering only 'to inform', state what the writer wants the audience to understand, for example, 'to explain how coastal flooding can be reduced'."]}],"keyPoints":["Texts may mix purposes but one is usually dominant.","Purpose and audience shape language choices.","Form provides clues about intended audience.","A precise purpose includes the topic or intended outcome.","Informative writing prioritises clear factual communication."],"summary":"Identify who the text addresses, why it exists and how its language supports that purpose.","cards":[{"front":"Main purpose of informative discourse?","back":"To inform, explain, report or instruct clearly."},{"front":"Main purpose of persuasive discourse?","back":"To influence belief, attitude or action."},{"front":"What can reveal intended audience?","back":"Vocabulary, assumed knowledge, tone, examples and text form."},{"front":"Why is 'to inform' often too vague?","back":"A precise purpose should state what the audience is meant to learn."},{"front":"Can one text have mixed purposes?","back":"Yes, but exam questions usually ask for the dominant purpose."}]},{"id":"1.7-diction-grammar-editing","section":"module-1","order":107,"title":"1.7 Diction, Grammar and Editing for Clarity","objectives":["Use appropriate diction and grammatical forms to convey meaning clearly.","Use punctuation accurately and edit common language errors."],"intro":"Editing is the process of improving accuracy and clarity after ideas have been drafted. CSEC Paper 1 may test whether you can identify the version of a sentence that is grammatically and stylistically sound.","sections":[{"title":"Diction","paragraphs":["Diction means word choice. Strong diction is accurate, natural and suited to the audience. Avoid vague words when a precise one is available, and avoid unnecessarily complicated vocabulary."],"bullets":["Choose the right register.","Check idioms and fixed phrases.","Distinguish near-synonyms by context.","Prefer precise verbs over weak verb-plus-adverb combinations where possible."]},{"title":"Grammar checks","paragraphs":["Common areas include subject-verb agreement, pronoun reference, possessives, number, sequence of tenses and sentence boundaries."],"bullets":["Find the real subject before choosing the verb.","Make sure each pronoun clearly refers to a noun.","Avoid fragments and run-on sentences.","Shift tense only when the time frame changes."]},{"title":"Editing routine","paragraphs":["Read once for meaning, once for sentence structure and once for mechanics. This is more reliable than trying to notice every type of error at the same time."]}],"keyPoints":["Diction should be precise and appropriate.","Agreement depends on the true subject.","Pronoun reference must be clear.","Tense should follow the time sequence.","Effective editing happens in focused passes."],"summary":"Clear informative writing comes from accurate word choice, grammar, punctuation and deliberate editing.","cards":[{"front":"What is diction?","back":"A writer’s or speaker’s choice of words."},{"front":"What is a pronoun-reference error?","back":"A pronoun does not clearly identify the noun it refers to."},{"front":"What causes a run-on sentence?","back":"Independent clauses are joined incorrectly or without proper punctuation."},{"front":"When should tense change?","back":"When the time frame genuinely changes."},{"front":"Useful editing strategy?","back":"Read in separate passes for meaning, grammar and mechanics."}]},{"id":"1.8-conclusions-main-ideas-connotation","section":"module-1","order":108,"title":"1.8 Conclusions, Main Ideas and Connotation","objectives":["Draw valid conclusions and inferences.","Trace main and subordinate ideas.","Distinguish denotative from connotative language."],"intro":"A strong reader follows how ideas develop, notices which ideas are central and judges whether a conclusion is actually supported by the evidence.","sections":[{"title":"Valid conclusions","paragraphs":["A valid conclusion follows logically from the information available. Watch for sweeping generalisations drawn from tiny or biased samples."],"bullets":["Separate evidence from assumption.","Check whether the sample is representative.","Avoid words such as always and never unless the evidence justifies them."]},{"title":"Main and subordinate ideas","paragraphs":["The main idea is the central point a section develops. Subordinate ideas explain, illustrate, qualify or support it. Topic sentences help, but the main idea can also be implied."],"bullets":["Ask what all the key details have in common.","Notice repeated ideas and emphasis.","Do not mistake an interesting example for the central point."]},{"title":"Connotation and bias","paragraphs":["Two words may refer to the same thing but create different feelings. Calling a plan 'ambitious' and calling it 'reckless' can lead readers toward different judgements."]}],"keyPoints":["Conclusions must fit the evidence.","Biased samples produce weak generalisations.","Main ideas organise supporting details.","Examples are not automatically main ideas.","Connotation can reveal slant or bias."],"summary":"Evaluate evidence, follow the hierarchy of ideas and notice how loaded language influences interpretation.","cards":[{"front":"What makes a conclusion valid?","back":"It follows logically from sufficient relevant evidence."},{"front":"What is a subordinate idea?","back":"A detail that explains, supports or develops a main idea."},{"front":"What is a biased sample?","back":"A sample that does not fairly represent the wider group."},{"front":"Denotation versus connotation?","back":"Denotation is direct meaning; connotation is associated feeling."},{"front":"How can connotation reveal bias?","back":"Loaded words can push readers toward a particular judgement."}]},{"id":"1.9-visual-information-informative-writing","section":"module-1","order":109,"title":"1.9 Visual Information and Informative Writing","objectives":["Interpret tables, charts, diagrams, signs and other visual information.","Communicate factual information clearly in instructions, reports, summaries and expositions."],"intro":"English A treats visual literacy as part of language. You must be able to extract, compare and explain information presented in non-paragraph forms, then communicate it accurately.","sections":[{"title":"Reading visuals","paragraphs":["Begin with the title, labels, legend, units and time period. Then identify patterns, extremes, changes and comparisons. Do not infer more than the visual actually shows."],"bullets":["Tables organise exact values.","Graphs highlight patterns and trends.","Maps depend on keys, symbols and scale.","Advertisements combine words and visual design for a purpose."]},{"title":"Turning visual data into words","paragraphs":["A good verbal summary selects the most important pattern rather than copying every number. Use comparisons accurately: increased by is different from increased to, and percentage points are different from percent change."]},{"title":"Informative forms","paragraphs":["Instructions use clear ordered steps. Reports organise findings for a defined purpose. Summaries condense the essential meaning without unnecessary detail. Expositions explain a subject logically using relevant evidence."]}],"keyPoints":["Read labels and units before interpreting data.","Describe patterns without exaggeration.","Select important information instead of copying everything.","Different informative forms have different conventions.","Clarity and concision matter in every factual response."],"summary":"Visual interpretation and informative writing both require accurate selection, organisation and communication of evidence.","cards":[{"front":"First things to check on a chart?","back":"Title, labels, legend, units and time period."},{"front":"What should a data summary emphasise?","back":"The most important patterns, comparisons and changes."},{"front":"Purpose of instructions?","back":"To guide someone through ordered steps clearly."},{"front":"Purpose of a summary?","back":"To condense the essential meaning accurately and concisely."},{"front":"Key rule when interpreting visuals?","back":"Do not claim more than the data actually shows."}]},{"id":"2.1-language-literary-meaning","section":"module-2","order":201,"title":"2.1 Language, Word Choice and Literary Meaning","objectives":["Explain how word choice, grammar, punctuation and paragraphing create meaning in literary texts.","Identify effective parts of speech, word combinations and unusual turns of phrase."],"intro":"Literary language often does more than transmit information. Writers choose sounds, images, sentence patterns and punctuation to shape the reader’s experience.","sections":[{"title":"Word choice in literature","paragraphs":["A precise verb can reveal attitude or character, while an adjective may create atmosphere. In literary questions, explain what the choice suggests in that particular context."],"bullets":["Concrete words appeal to the senses.","Abstract words name ideas or qualities.","Unusual combinations can make an image memorable.","Repetition can add emphasis, rhythm or emotional pressure."]},{"title":"Grammar and punctuation as craft","paragraphs":["Short sentences can quicken pace or create shock. Longer sentences may slow the reader or mirror reflection. Dashes, ellipses, exclamation marks and paragraph breaks can shape voice and timing."],"bullets":["Ask how form supports meaning.","Do not identify a feature without explaining its effect.","Consider the surrounding sentences before judging tone."]},{"title":"From identification to explanation","paragraphs":["A complete literary response links technique, evidence and effect: what the writer does, where it appears and how it contributes to meaning."]}],"keyPoints":["Literary word choice creates associations as well as meaning.","Sentence length can affect pace.","Punctuation can shape voice and emphasis.","Technique labels alone are not analysis.","Always connect language choice to effect."],"summary":"Literary language is purposeful: explain how specific choices shape meaning, mood and response.","cards":[{"front":"How can short sentences affect a story?","back":"They can quicken pace, add tension or create emphasis."},{"front":"Why use sensory words?","back":"They help readers imagine sights, sounds, textures, tastes or smells."},{"front":"What makes literary analysis complete?","back":"Link the technique and evidence to its effect or meaning."},{"front":"What can repetition do?","back":"Create emphasis, rhythm, pattern or emotional pressure."},{"front":"Why examine punctuation in literature?","back":"It can control pace, emphasis, voice and interpretation."}]},{"id":"2.2-explicit-implied-literature","section":"module-2","order":202,"title":"2.2 Explicit and Implied Meaning in Literature","objectives":["Identify explicitly stated information in literary texts.","Extract implied information and make supported inferences."],"intro":"Literary texts often leave important ideas unstated. A character’s silence, a repeated object or a change in behaviour can reveal more than direct explanation.","sections":[{"title":"Explicit meaning","paragraphs":["Explicit information is directly stated. Questions about who, what, where and when often begin here, but accuracy still matters because distractors may alter one detail."]},{"title":"Implicit meaning","paragraphs":["Inference involves reading clues and reaching a logical interpretation. In literature, clues may come from dialogue, actions, setting, contrasts, imagery or what a character avoids saying."],"bullets":["Quote or identify the clue first.","Ask what the clue reasonably suggests.","Check that another detail does not contradict your inference."]},{"title":"Character inference","paragraphs":["Do not label a character with a trait simply because of one action. Look for patterns or strong contextual evidence, especially when the question asks for the best description."]}],"keyPoints":["Explicit information is directly stated.","Implicit meaning must be inferred.","Literary inference uses dialogue, action, setting and imagery.","Strong inferences fit the whole context.","Character traits require evidence."],"summary":"Read both the surface information and the clues beneath it, but keep every interpretation anchored in the text.","cards":[{"front":"What is explicit information?","back":"Information stated directly in the text."},{"front":"What is implicit meaning?","back":"Meaning suggested through clues rather than directly stated."},{"front":"Useful clues for literary inference?","back":"Dialogue, actions, setting, contrast, imagery and silence."},{"front":"How should you test an inference?","back":"Check that the whole text supports it and does not contradict it."},{"front":"Why avoid judging character from one action?","back":"One action may not represent the character’s usual nature or motive."}]},{"id":"2.3-point-of-view-sequence","section":"module-2","order":203,"title":"2.3 Narrative Point of View and Sequence","objectives":["Identify stated or implied sequence in literary texts.","Recognise narrative point of view and how it shapes information."],"intro":"Who tells a story affects what the reader knows, trusts and notices. Sequence also shapes suspense, surprise and understanding.","sections":[{"title":"Point of view","paragraphs":["First-person narration uses I or we and limits the reader to that narrator’s knowledge. Third-person narration uses he, she or they; it may stay close to one character or move more widely."],"bullets":["First person can feel immediate and personal.","A limited narrator may misunderstand events.","An omniscient narrator can reveal thoughts of multiple characters."]},{"title":"Sequence","paragraphs":["Writers may present events chronologically or interrupt the timeline with flashback, memory or foreshadowing. These choices can reveal information gradually."],"bullets":["Flashback shows an earlier event.","Foreshadowing hints at what may happen later.","In medias res begins in the middle of action."]},{"title":"Effect","paragraphs":["When asked about point of view or sequence, explain the consequence for the reader: what information is delayed, emphasised, hidden or made more personal."]}],"keyPoints":["Point of view controls access to information.","First person is not automatically reliable.","Flashback reveals earlier events.","Foreshadowing creates expectation.","Narrative structure can build suspense or surprise."],"summary":"Point of view and sequence are structural choices that control how readers receive and interpret a story.","cards":[{"front":"What marks first-person narration?","back":"The narrator uses I or we and tells events from that perspective."},{"front":"What is an omniscient narrator?","back":"A narrator who can know the thoughts or experiences of multiple characters."},{"front":"What is a flashback?","back":"A shift to an event that happened earlier."},{"front":"What is foreshadowing?","back":"A hint or clue about something that may happen later."},{"front":"Why analyse sequence?","back":"It can control suspense, revelation, emphasis and reader expectations."}]},{"id":"2.4-literary-devices-elements","section":"module-2","order":204,"title":"2.4 Literary Devices and Elements","objectives":["Identify literary devices and techniques.","Explain how literary elements contribute to meaning."],"intro":"CSEC expects more than memorised definitions. You should recognise a device in context and explain why the writer uses it.","sections":[{"title":"Common devices","paragraphs":["Important devices include simile, metaphor, personification, symbolism, irony, exaggeration, pun and imagery. Sound techniques such as alliteration and onomatopoeia may also contribute to effect."],"bullets":["Simile compares using like or as.","Metaphor makes a direct comparison.","Personification gives human qualities to non-human things.","Symbolism gives an object, place or action wider meaning.","Irony creates a contrast between expectation and reality."]},{"title":"Literary elements","paragraphs":["Plot, character, setting, conflict, theme and point of view work together. A question may focus on one element but expect you to connect it to the whole text."],"bullets":["Setting includes place, time and social environment.","Conflict drives tension and choice.","Characterisation is how the writer reveals character.","Theme is an underlying concern or idea, not a one-word topic alone."]},{"title":"Effect matters","paragraphs":["Avoid answers such as 'the writer uses a metaphor to make it interesting'. Explain the specific idea or feeling the device creates in the passage."]}],"keyPoints":["Identify devices in context.","Literary elements interact.","Theme is a developed idea, not just a topic.","Setting includes social and historical surroundings.","Analysis must explain specific effect."],"summary":"Know the names of literary techniques, but focus most on what they achieve in the text.","cards":[{"front":"What is personification?","back":"Giving human qualities or actions to something non-human."},{"front":"What is symbolism?","back":"Using something concrete to represent a wider idea or meaning."},{"front":"What is irony?","back":"A meaningful contrast between expectation, appearance or words and reality."},{"front":"What does setting include?","back":"Place, time and the social environment of the action."},{"front":"Better than saying 'it is interesting'?","back":"Explain the exact idea, feeling, image or response the technique creates."}]},{"id":"2.5-attitudes-values-motivation","section":"module-2","order":205,"title":"2.5 Attitudes, Values and Character Motivation","objectives":["Recognise attitudes and values in literary texts.","Deduce reasons and motives for characters’ speech and actions."],"intro":"Characters reveal what they value through choices, words, reactions and relationships. Writers may also invite readers to question those values.","sections":[{"title":"Attitude and value","paragraphs":["An attitude is a way of thinking or feeling about something. A value is a principle or belief considered important. Neither has to be directly announced."],"bullets":["Look for repeated choices and reactions.","Notice what a character praises, condemns, protects or sacrifices.","Separate a character’s values from the writer’s overall viewpoint."]},{"title":"Motivation","paragraphs":["Motivation is the reason behind an action. A strong inference about motive considers context, previous behaviour, pressure from other characters and possible consequences."],"bullets":["Immediate motive explains a specific action.","Deeper motive may come from fear, loyalty, pride, ambition or insecurity.","Mixed motives are possible."]},{"title":"Evidence","paragraphs":["Choose the explanation that accounts for the most evidence with the fewest unsupported assumptions."]}],"keyPoints":["Attitude concerns a response or viewpoint.","Values are principles considered important.","Motivation explains why a character acts.","Characters may have mixed motives.","The writer and a character do not necessarily share the same values."],"summary":"Use patterns of language and behaviour to infer attitudes, values and motives without overreaching.","cards":[{"front":"What is an attitude?","back":"A way of thinking or feeling about a person, issue or situation."},{"front":"What is a value?","back":"A principle or belief a person or society considers important."},{"front":"What is character motivation?","back":"The reason or combination of reasons behind a character’s actions."},{"front":"Can a character have mixed motives?","back":"Yes. More than one desire or pressure can influence an action."},{"front":"Does a character speak for the writer?","back":"Not necessarily; the text may question or criticise that character’s view."}]},{"id":"2.6-diction-grammar-literary-response","section":"module-2","order":206,"title":"2.6 Diction, Grammar and Punctuation in Literary Responses","objectives":["Use appropriate diction and grammatical forms in literary responses.","Use punctuation accurately to communicate meaning."],"intro":"A good idea loses marks if the reader cannot follow it. Literary responses need accurate language, clear sentences and suitable terminology.","sections":[{"title":"Precise analytical diction","paragraphs":["Use verbs that describe what the writer does: suggests, contrasts, reveals, emphasises, foreshadows, symbolises and reinforces. Avoid vague claims such as 'this shows a lot'."],"bullets":["Name the technique only when you can explain it.","Use present tense when discussing what a text does, unless context requires otherwise.","Choose evidence that directly supports the point."]},{"title":"Sentence control","paragraphs":["Combine short and longer sentences to keep analysis readable. Use subordinate clauses when explaining cause, contrast or effect, but avoid sentences so long that the main point disappears."]},{"title":"Punctuation","paragraphs":["Use quotation marks for brief quoted words or phrases, commas to separate introductory elements, colons to introduce explanations and apostrophes accurately for possession."]}],"keyPoints":["Analytical verbs make commentary precise.","Evidence should match the claim.","Sentence variety supports clarity.","Literary analysis commonly uses present tense.","Accurate punctuation protects meaning."],"summary":"Clear literary analysis depends on precise vocabulary, controlled grammar and accurate punctuation.","cards":[{"front":"Useful analytical verb for a contrast?","back":"Contrasts, juxtaposes or highlights, depending on the context."},{"front":"Usual tense for discussing a text?","back":"Present tense, unless a different time reference is required."},{"front":"What should evidence do?","back":"Directly support the analytical point being made."},{"front":"Why vary sentence structure?","back":"To keep ideas clear and show relationships without monotony."},{"front":"What do quotation marks show in analysis?","back":"Exact words or phrases taken from the text."}]},{"id":"2.7-connotation-form-purpose","section":"module-2","order":207,"title":"2.7 Connotation, Form, Structure and Writer’s Purpose","objectives":["Detect connotations in literary language.","Explain how form and structure help a writer achieve purpose."],"intro":"Meaning comes not only from what a writer says but from the form chosen and the order in which the material is presented.","sections":[{"title":"Connotation","paragraphs":["Connotative meaning adds emotional or cultural associations to a word. A 'home' and a 'house' may refer to the same building, but home often carries stronger feelings of belonging."],"bullets":["Notice loaded or repeated words.","Compare alternative words the writer could have used.","Ask what attitude the chosen word encourages."]},{"title":"Form","paragraphs":["Form is the broad type of text, such as poem, short story, diary, letter or dramatic scene. Each form offers different possibilities for voice, organisation and audience relationship."]},{"title":"Structure","paragraphs":["Structure is how the parts are arranged. Repetition, contrast, shifts in time, stanza breaks, paragraph order and beginnings or endings can direct attention and shape response."]}],"keyPoints":["Connotation adds associations beyond direct meaning.","Form is the type or shape of the work.","Structure is the arrangement of its parts.","Beginnings and endings often carry special emphasis.","Explain how structural choices support purpose."],"summary":"Word associations, form and structure work together to guide interpretation and achieve the writer’s purpose.","cards":[{"front":"What is connotative meaning?","back":"The emotional, cultural or personal associations a word carries."},{"front":"What is literary form?","back":"The broad type of work, such as poem, story, diary, letter or drama."},{"front":"What is literary structure?","back":"How parts of the work are arranged and connected."},{"front":"Why compare a chosen word with alternatives?","back":"It helps reveal the attitude or effect created by that exact choice."},{"front":"What can stanza or paragraph breaks do?","back":"Control grouping, pace, contrast and emphasis."}]},{"id":"2.8-theme-tone-mood-register-style","section":"module-2","order":208,"title":"2.8 Theme, Tone, Mood, Register, Code and Style","objectives":["Analyse implicit themes.","Interpret tone, mood, register, code and style in relation to the writer’s intention."],"intro":"These terms are related but not interchangeable. Knowing the difference helps you answer literary questions precisely.","sections":[{"title":"Theme","paragraphs":["A theme is an idea or concern explored across a text. State it as a meaningful idea, for example, 'courage can involve acting despite fear', rather than simply 'courage'."],"bullets":["Themes can be explicit or implied.","Trace a theme through events, images, choices and consequences.","Support theme statements with evidence."]},{"title":"Tone and mood","paragraphs":["Tone is the attitude expressed by the speaker, narrator or writer. Mood is the feeling or atmosphere experienced in the work. A sarcastic tone may create a humorous or uncomfortable mood."],"bullets":["Tone belongs to the voice.","Mood describes atmosphere or reader experience.","Both can shift during a text."]},{"title":"Register, code and style","paragraphs":["Register is the level and type of language suited to a situation. Code is language associated with a particular group. Style is the writer’s characteristic manner of expression, including structure, diction and sentence patterns."]}],"keyPoints":["Theme is a developed idea.","Tone is attitude; mood is atmosphere.","Register changes with situation and audience.","Code can signal group identity.","Style combines many language and structural choices."],"summary":"Use the correct term, then connect it to evidence and the writer’s intention.","cards":[{"front":"Theme versus topic?","back":"A topic is a subject; a theme is an idea the text develops about it."},{"front":"Tone versus mood?","back":"Tone is the voice’s attitude; mood is the atmosphere or feeling created."},{"front":"What is register?","back":"Language chosen for a particular level of formality, purpose and situation."},{"front":"What is code?","back":"Language or expressions associated with a particular group."},{"front":"What is style?","back":"The writer’s manner of expression through language, form and structure."}]},{"id":"2.9-writers-craft-context","section":"module-2","order":209,"title":"2.9 Evaluating Writer’s Craft and Socio-historical Context","objectives":["Evaluate the writer’s choice of literary elements and techniques.","Explore how socio-historical context influences literary works."],"intro":"Evaluation goes beyond identifying a technique. You judge how effectively a choice works for the audience, purpose and context.","sections":[{"title":"Evaluating craft","paragraphs":["Ask whether the chosen technique strengthens character, theme, atmosphere, conflict or another important aspect of the work. Use evidence and explain the result."],"bullets":["Effective does not mean 'I like it'.","Evaluation needs a reasoned judgement.","Consider whether another choice would have produced a different effect."]},{"title":"Socio-historical context","paragraphs":["A work is shaped by the society and period in which it is produced or set. Class, gender expectations, migration, colonial history, technology, religion and economic conditions may influence characters and conflicts."],"bullets":["Context should illuminate the text, not replace close reading.","Avoid assuming every character represents an entire culture.","Use only context that is relevant to the question."]},{"title":"Caribbean connection","paragraphs":["The syllabus encourages engagement with Caribbean voices and experiences. Pay attention to regional language, community relationships and historical realities where they are relevant to the text."]}],"keyPoints":["Evaluation is a supported judgement.","Writer’s craft includes language, structure and literary technique.","Context can shape character, conflict and values.","Relevant context supports close reading.","Caribbean literature may draw on distinctive regional experiences and language."],"summary":"Judge how well literary choices work and use relevant context to deepen, not replace, textual analysis.","cards":[{"front":"What makes a literary judgement evaluative?","back":"It gives a reasoned judgement supported by evidence and effect."},{"front":"What is socio-historical context?","back":"The social and historical conditions surrounding a work or its setting."},{"front":"How should context be used?","back":"To deepen interpretation of specific textual evidence."},{"front":"What should context NOT do?","back":"Replace close reading or lead to unsupported cultural assumptions."},{"front":"What counts as writer’s craft?","back":"Choices of language, form, structure, characterisation and literary technique."}]},{"id":"2.10-literary-response-creative-writing","section":"module-2","order":210,"title":"2.10 Literary Responses and Creative Writing","objectives":["Create coherent literary responses with suitable paragraphing.","Use literary understanding to create and evaluate imaginative writing."],"intro":"The revised English A syllabus connects reading and creating. Studying how writers shape character, setting, conflict and language can improve your own imaginative writing.","sections":[{"title":"Analytical paragraph","paragraphs":["A useful structure is point, evidence, explanation and link. The exact order can vary, but every paragraph should make one clear claim and explain how the evidence supports it."],"bullets":["Point: answer part of the question.","Evidence: select a relevant detail or brief quotation.","Explanation: analyse meaning and effect.","Link: connect back to the main argument when useful."]},{"title":"Creative craft","paragraphs":["Strong imaginative writing uses selective detail. Establish a believable situation, develop conflict or tension, control point of view and choose details that reveal character rather than explaining everything directly."]},{"title":"Revision","paragraphs":["After drafting, check whether every scene or paragraph has a purpose. Remove repetition, strengthen weak verbs, check dialogue punctuation and make sure the ending grows naturally from what came before."]}],"keyPoints":["One analytical paragraph should develop one main claim.","Evidence must be explained.","Creative writing benefits from controlled point of view.","Specific detail is stronger than excessive description.","Revision improves structure as well as grammar."],"summary":"Use the same awareness of craft when analysing literature and when creating your own writing.","cards":[{"front":"Core parts of an analytical paragraph?","back":"A clear point, relevant evidence and explanation of how the evidence supports the point."},{"front":"Why control point of view in a story?","back":"It determines what the reader knows and how events are experienced."},{"front":"What is selective detail?","back":"Choosing a few meaningful details instead of describing everything."},{"front":"What should revision examine besides grammar?","back":"Purpose, structure, repetition, pace, evidence and clarity."},{"front":"Why explain evidence?","back":"Evidence alone does not show how it supports the argument."}]},{"id":"3.1-language-persuasive-meaning","section":"module-3","order":301,"title":"3.1 Word Choice, Grammar and Persuasive Meaning","objectives":["Explain how word choice, grammar, punctuation and paragraphing shape persuasive meaning.","Recognise effective word combinations and parts of speech."],"intro":"Persuasive language is chosen to influence how an audience thinks or feels. Good readers notice both the message and the choices used to frame it.","sections":[{"title":"Loaded language","paragraphs":["Loaded words carry strong positive or negative connotations. Calling a proposal 'bold' rather than 'reckless' can shape the audience’s judgement before evidence is considered."],"bullets":["Identify the emotionally charged word.","Ask what attitude it encourages.","Consider a more neutral alternative."]},{"title":"Sentence choices","paragraphs":["Imperatives can sound direct and urgent. Short sentences can create force. Parallel structures can make a message memorable. Questions can involve the audience or guide them toward a conclusion."]},{"title":"Punctuation and paragraphing","paragraphs":["Persuasive texts use punctuation and paragraph placement to control emphasis. A one-sentence paragraph can spotlight a call to action, while a colon can introduce evidence or a decisive explanation."]}],"keyPoints":["Persuasive meaning depends on framing.","Loaded language carries evaluative connotation.","Sentence form can create urgency or emphasis.","Parallel structure adds rhythm and memorability.","Paragraph placement can highlight key claims."],"summary":"Analyse persuasive language by asking how each choice guides the audience’s response.","cards":[{"front":"What is loaded language?","back":"Words with strong positive or negative associations that influence judgement."},{"front":"What can an imperative do?","back":"Direct or urge the audience to take action."},{"front":"Why use parallel structure?","back":"To create rhythm, balance and memorability."},{"front":"How can a short paragraph persuade?","back":"It can isolate and emphasise a key claim or call to action."},{"front":"How do you test for loaded wording?","back":"Replace it with a neutral term and compare the effect."}]},{"id":"3.2-fact-opinion-implication-sequence","section":"module-3","order":302,"title":"3.2 Facts, Opinions, Implication and Sequence","objectives":["Identify facts and opinions in persuasive material.","Extract implied information and follow stated or implied sequence."],"intro":"Persuasive texts often mix verifiable facts with interpretation. A careful reader tracks which claims are proven, which are opinions and which ideas are implied.","sections":[{"title":"Evidence versus claim","paragraphs":["A persuasive claim may be supported by facts, examples, expert views or statistics. The presence of evidence does not make every sentence factual."],"bullets":["Ask whether the statement can be verified.","Separate the raw evidence from the writer’s interpretation.","Check whether the evidence is relevant to the conclusion."]},{"title":"Implication","paragraphs":["Writers may imply that a choice is irresponsible, modern, dangerous or desirable without saying so directly. Connotation, comparison and selective detail can create these suggestions."]},{"title":"Sequence of argument","paragraphs":["Persuasive arguments may move from problem to evidence to proposal, or from claim to counterargument to rebuttal. Recognising the sequence helps you judge how the argument develops."]}],"keyPoints":["Facts and opinions can appear together.","Evidence does not automatically prove a conclusion.","Implications can be created through framing.","Arguments have an order and structure.","Track how each stage supports the final position."],"summary":"Separate evidence from opinion, infer carefully and follow the progression of the argument.","cards":[{"front":"Can an opinion use factual evidence?","back":"Yes. Evidence may support a judgement without turning the judgement into a fact."},{"front":"What is a claim?","back":"A position or assertion the writer wants the audience to accept."},{"front":"What is a rebuttal?","back":"A response that challenges or answers an opposing argument."},{"front":"How can implication be created?","back":"Through connotation, contrast, omission, comparison and selective detail."},{"front":"Why trace argument sequence?","back":"To see how reasons and evidence build toward the writer’s conclusion."}]},{"id":"3.3-connotation-bias-perspective","section":"module-3","order":303,"title":"3.3 Connotation, Bias and Perspective","objectives":["Detect connotations and particular perspectives in persuasive language.","Distinguish neutral description from biased framing."],"intro":"Bias does not always appear as an obvious false statement. It can emerge through selection, omission, labels, images and the order in which information is presented.","sections":[{"title":"Perspective","paragraphs":["Perspective is the position from which an issue is viewed. Two writers may describe the same event accurately yet emphasise different details because their priorities differ."],"bullets":["Ask whose interests are represented.","Notice whose voice is absent.","Compare labels used for the same people or actions."]},{"title":"Bias","paragraphs":["Bias is a tendency that favours one side or viewpoint. Evidence of bias may include loaded language, one-sided evidence, stereotypes or unfair generalisations."],"bullets":["Bias is not proved merely because a writer has an opinion.","Look for how evidence is selected and framed.","Check whether counter-evidence is ignored or dismissed without reason."]},{"title":"Neutral rewrite","paragraphs":["A useful test is to rewrite the statement using neutral terms. The difference reveals how much persuasive force came from connotation rather than evidence."]}],"keyPoints":["Perspective shapes selection and emphasis.","Bias favours a viewpoint in a way that can distort fairness.","Loaded labels can frame people before evidence is considered.","Omission can contribute to bias.","Neutral rewriting helps reveal persuasive framing."],"summary":"Identify the viewpoint, examine the evidence and notice how language encourages the audience to see the issue.","cards":[{"front":"What is perspective?","back":"The position or viewpoint from which an issue is presented."},{"front":"What is bias?","back":"A tendency to favour a viewpoint in a way that may reduce fairness or balance."},{"front":"Does having an opinion prove bias?","back":"No. Bias is shown by unfair framing, selection or treatment of evidence."},{"front":"How can omission create bias?","back":"Important contrary information may be left out, making one side appear stronger."},{"front":"Useful test for loaded language?","back":"Rewrite it neutrally and compare the change in effect."}]},{"id":"3.4-persuasive-devices","section":"module-3","order":304,"title":"3.4 Persuasive Devices and Techniques","objectives":["Identify persuasive devices used in social discourse and mass media.","Explain the intended effect of persuasive techniques."],"intro":"Persuasive devices are tools, not magic formulas. Their effectiveness depends on audience, context, credibility and how well they support the message.","sections":[{"title":"Common techniques","paragraphs":["The syllabus includes appeals to authority, desire, fear and emotion; statistics; association; contrast; ridicule; rhetorical questions; repetition; hyperbole; irony; sarcasm; paradox; oxymoron and other devices."],"bullets":["Authority uses a respected source or expert.","Emotional appeal targets feelings.","Statistics create an impression of measurable evidence.","Rhetorical questions guide thought rather than seek an answer.","Repetition reinforces a message.","Contrast makes one option appear stronger beside another."]},{"title":"Visual and auditory persuasion","paragraphs":["Colour, size, placement, facial expression, music and sound can influence response. In a visual question, explain how the feature directs attention or creates association."],"bullets":["Large type can establish hierarchy.","Images can create identification or aspiration.","Music can set emotional tone.","Layout can control what is noticed first."]},{"title":"Evaluate effect","paragraphs":["Name the technique, identify the target audience and explain the likely effect. Do not assume a technique works equally well on everyone."]}],"keyPoints":["Persuasive devices work differently for different audiences.","Statistics can persuade but should still be evaluated.","Rhetorical questions are usually asked for effect.","Visual design is part of persuasion.","Explain intended effect, not just the device name."],"summary":"Recognise verbal, visual and auditory techniques, then explain how they are meant to influence a particular audience.","cards":[{"front":"What is an appeal to authority?","back":"Using an expert or respected source to increase credibility."},{"front":"What is a rhetorical question?","back":"A question asked mainly for effect rather than an actual answer."},{"front":"What is hyperbole?","back":"Deliberate exaggeration for emphasis or effect."},{"front":"How can layout persuade?","back":"It controls attention, emphasis and the order in which information is noticed."},{"front":"Best way to explain a persuasive device?","back":"Name it, identify the audience and state its intended effect in context."}]},{"id":"3.5-persuasive-essay-evidence","section":"module-3","order":305,"title":"3.5 Persuasive Essay Structure and Evidence","objectives":["Identify techniques used to produce persuasive essays.","Recognise claims, reasons, evidence, counterarguments and rebuttals."],"intro":"A persuasive essay succeeds through reasoning as well as language. It states a position, supports it and deals fairly with significant opposing views.","sections":[{"title":"Core structure","paragraphs":["A clear introduction establishes the issue and position. Body paragraphs develop distinct reasons with evidence. A conclusion reinforces the position without merely repeating every sentence."],"bullets":["Thesis: the central position.","Topic sentence: the focus of a body paragraph.","Evidence: facts, examples, data or credible testimony.","Explanation: why the evidence supports the claim."]},{"title":"Counterargument and rebuttal","paragraphs":["Acknowledging a serious opposing point can strengthen credibility. A rebuttal should answer it with reasoning or evidence rather than dismissing the people who hold it."],"bullets":["Address the idea, not the person.","Concede a valid point when appropriate.","Show why your position remains stronger overall."]},{"title":"Evidence quality","paragraphs":["Relevant evidence connects directly to the claim. Reliable evidence comes from credible sources and sound methods. A large number of weak examples does not equal strong proof."]}],"keyPoints":["A thesis states the central position.","Each body paragraph should develop a clear reason.","Evidence needs explanation.","Counterarguments can strengthen credibility.","Judge evidence for relevance and reliability."],"summary":"Strong persuasion combines clear structure, credible evidence and fair treatment of opposing views.","cards":[{"front":"What is a thesis statement?","back":"The central position or controlling claim of the argument."},{"front":"What should follow evidence?","back":"Explanation showing how the evidence supports the claim."},{"front":"What is a counterargument?","back":"A significant opposing view or objection."},{"front":"What is a rebuttal?","back":"A reasoned answer to a counterargument."},{"front":"Two qualities of strong evidence?","back":"It is relevant to the claim and comes from a credible basis."}]},{"id":"3.6-diction-grammar-clear-argument","section":"module-3","order":306,"title":"3.6 Diction, Grammar, Punctuation and Clear Argument","objectives":["Use appropriate diction and grammatical forms in persuasive communication.","Use punctuation accurately to keep arguments clear."],"intro":"Persuasive force is weakened when the audience cannot follow the sentence or when careless wording damages credibility.","sections":[{"title":"Appropriate diction","paragraphs":["Match wording to the audience and occasion. A letter to an editor may be firm and formal; a youth campaign speech may be energetic but still clear and respectful."],"bullets":["Use precise words instead of vague intensifiers.","Avoid insults when reasoned criticism will be stronger.","Keep terms consistent throughout the argument."]},{"title":"Grammar for logic","paragraphs":["Grammar shows relationships among claims. Subordination can distinguish a main claim from a concession, while conjunctions such as because, although and therefore signal reasoning."],"bullets":["Check agreement and pronoun reference.","Avoid ambiguous modifiers.","Use complete sentences unless a deliberate fragment is clearly effective."]},{"title":"Punctuation for argument","paragraphs":["Colons can introduce evidence, commas can mark transitions and qualifying phrases, and semi-colons can connect closely related claims. Accurate punctuation prevents misreading."]}],"keyPoints":["Register should suit audience and occasion.","Grammar helps show logical relationships.","Transitions should reflect real reasoning.","Insults rarely strengthen evidence.","Punctuation can clarify the structure of an argument."],"summary":"Clear persuasive writing uses precise, appropriate language and grammar that makes the reasoning easy to follow.","cards":[{"front":"Why does register matter in persuasion?","back":"The audience is more likely to engage with language suited to the occasion."},{"front":"What can 'although' signal?","back":"A concession or contrast."},{"front":"What can 'therefore' signal?","back":"A conclusion or result based on earlier reasoning."},{"front":"Why avoid vague intensifiers?","back":"Precise evidence and wording are more convincing than words like very or really."},{"front":"How does punctuation support argument?","back":"It clarifies grouping, transitions, evidence and relationships among claims."}]},{"id":"3.7-reasoning-conclusions-main-ideas","section":"module-3","order":307,"title":"3.7 Reasoning, Conclusions and Main Ideas","objectives":["Draw valid conclusions and detect faulty reasoning.","Trace the development of main and subordinate ideas.","Distinguish factual statements from opinions."],"intro":"Persuasion should be judged by the quality of its reasoning, not only by confidence or emotional force.","sections":[{"title":"Sound reasoning","paragraphs":["A conclusion should follow from relevant evidence. Common weaknesses include overgeneralising from a small sample, assuming that sequence proves causation and attacking a person instead of the argument."],"bullets":["Ask whether the evidence is sufficient.","Ask whether it actually relates to the claim.","Look for missing alternatives or assumptions."]},{"title":"Argument hierarchy","paragraphs":["The main claim is supported by reasons; reasons may be supported by evidence and examples. Mapping this hierarchy helps you see whether a paragraph genuinely advances the argument."],"bullets":["Main claim: what the writer wants accepted.","Reason: why the claim should be accepted.","Evidence: what supports the reason.","Example: a case that illustrates the point."]},{"title":"Fact and opinion","paragraphs":["A factual statement is verifiable even if it later proves false. An opinion expresses a judgement. Strong arguments often combine both, so classify each statement by what it is doing."]}],"keyPoints":["Confidence is not proof.","Conclusions require relevant sufficient evidence.","Sequence does not automatically prove causation.","Arguments contain levels of claim, reason and evidence.","A factual claim can be wrong but still be factual in type."],"summary":"Test the logic behind persuasive claims and trace how supporting ideas contribute to the central position.","cards":[{"front":"What is overgeneralisation?","back":"Drawing a broad conclusion from evidence that is too limited."},{"front":"Does 'after' prove 'because of'?","back":"No. Sequence alone does not prove cause."},{"front":"Claim, reason, evidence: which is proof?","back":"Evidence supports a reason, which in turn supports the claim."},{"front":"Can a factual statement be false?","back":"Yes. 'Factual' means it is verifiable, not automatically true."},{"front":"What is faulty personal attack reasoning?","back":"Attacking the person instead of addressing the argument."}]},{"id":"3.8-visual-persuasion-media","section":"module-3","order":308,"title":"3.8 Visual Persuasion and Media Messages","objectives":["Interpret tables, diagrams, cartoons, advertisements and other pictorial communication.","Explain how visual features and data are used to persuade."],"intro":"Paper 01 can combine words, numbers and images. Treat every part of a visual as intentional evidence: layout, scale, labels, images, colour, captions and statistics.","sections":[{"title":"Reading the whole visual","paragraphs":["Start with title and purpose, then inspect labels, images, size, placement and any data. Ask what catches the eye first and why."],"bullets":["Headline establishes the main message.","Image choice creates association.","Font size and position create hierarchy.","Statistics can make a message appear objective.","Fine print may qualify a bold claim."]},{"title":"Cartoons and symbols","paragraphs":["Cartoons often use exaggeration, labels, symbolism and irony. Identify the issue first, then explain how the visual features communicate the cartoonist’s viewpoint."]},{"title":"Data in persuasion","paragraphs":["Check what a graph actually measures. A truncated axis, selective time period or percentage without sample size can make a claim appear stronger than it is."]}],"keyPoints":["Visual hierarchy directs attention.","Images create associations.","Cartoons often rely on symbolism and irony.","Statistics need context.","Check axes, units, sample size and time period where available."],"summary":"Interpret visual and verbal elements together and judge whether the presentation fairly supports its persuasive message.","cards":[{"front":"What is visual hierarchy?","back":"The order in which design makes the viewer notice elements."},{"front":"What should you check on a persuasive graph?","back":"Axes, units, time period, source and scale."},{"front":"Why is fine print important?","back":"It may qualify, limit or explain a stronger headline claim."},{"front":"Common cartoon techniques?","back":"Exaggeration, symbolism, labels, contrast and irony."},{"front":"Can a true statistic mislead?","back":"Yes, if important context, scale or comparison is omitted."}]},{"id":"3.9-evaluative-comments-logical-argument","section":"module-3","order":309,"title":"3.9 Reasoned Comments, Emotional Appeals and Logical Arguments","objectives":["Communicate reasoned evaluative comments clearly.","Create persuasive communication that uses emotional appeal responsibly.","Present logical arguments with justifiable techniques."],"intro":"Persuasion can appeal to both reason and emotion. Effective communication knows when each is appropriate and avoids manipulation that damages credibility.","sections":[{"title":"Reasoned evaluation","paragraphs":["An evaluative comment states a judgement and gives reasons. Instead of 'the proposal is bad', explain which criterion it fails: cost, fairness, safety, feasibility or another relevant standard."],"bullets":["State the judgement.","Name the criterion.","Use evidence.","Explain the consequence."]},{"title":"Emotional appeal","paragraphs":["Emotion can motivate people to protect others, respond to danger or support a cause. It becomes weak or manipulative when it replaces evidence, exaggerates unfairly or exploits fear without justification."]},{"title":"Logical argument","paragraphs":["A logical argument connects claims through clear reasoning. Concessions, comparisons and examples are useful when they honestly represent the issue."],"bullets":["Avoid false either-or choices.","Do not distort the opposing view.","Use reasons that actually support the conclusion."]}],"keyPoints":["Evaluation uses criteria and evidence.","Emotion can support but should not replace reasoning.","Ethical persuasion avoids deception.","Concessions can improve credibility.","Logical links between reasons and conclusions must be clear."],"summary":"Persuade responsibly by combining justified judgement, appropriate emotion and sound reasoning.","cards":[{"front":"What makes a comment evaluative?","back":"It judges something using a relevant criterion and evidence."},{"front":"When is emotional appeal weak?","back":"When it replaces evidence or manipulates fear unfairly."},{"front":"What is a concession?","back":"Acknowledging a valid point made by the opposing side."},{"front":"What is a false dilemma?","back":"Presenting only two choices when other reasonable options exist."},{"front":"What is ethical persuasion?","back":"Influence that is honest, evidence-based and fair to the audience."}]},{"id":"3.10-informed-opinion-evaluating-persuasion","section":"module-3","order":310,"title":"3.10 Informed Opinion, Comparison and Evaluating Persuasion","objectives":["Research an issue from different perspectives to form an informed opinion.","Compare ideas and evaluate the effectiveness of persuasive techniques."],"intro":"An informed opinion is not simply a strong feeling. It is a position developed after examining credible evidence and more than one perspective.","sections":[{"title":"Research for persuasion","paragraphs":["Use sources that are relevant, current enough for the topic and credible. Compare claims across sources rather than accepting the first result that supports your view."],"bullets":["Check who produced the source.","Check what evidence is provided.","Check when it was produced.","Check whether the source has a clear interest in the outcome."]},{"title":"Comparing perspectives","paragraphs":["Two sources may agree on the problem but disagree on its cause or solution. Compare the exact points of agreement and disagreement before deciding which case is stronger."]},{"title":"Evaluating effectiveness","paragraphs":["A technique is effective when it advances the writer’s purpose for the intended audience. Judge clarity, credibility, evidence, emotional impact and fairness together."],"bullets":["Strong technique plus weak evidence can still produce a weak argument.","Audience matters: one appeal may work for one group and fail for another.","Explain why a device is effective in this exact context."]}],"keyPoints":["Informed opinions are evidence-based.","Use multiple perspectives.","Source credibility matters.","Compare precise claims, not vague 'sides'.","Evaluate persuasion by purpose, audience, evidence and effect."],"summary":"Form and evaluate opinions by researching broadly, comparing perspectives and judging how well persuasive choices work.","cards":[{"front":"What is an informed opinion?","back":"A reasoned position based on relevant evidence and consideration of different views."},{"front":"Four source checks?","back":"Producer, evidence, date and possible interest or bias."},{"front":"How should two perspectives be compared?","back":"Identify their exact agreements, disagreements, evidence and assumptions."},{"front":"What makes persuasion effective?","back":"It suits purpose and audience and uses credible evidence and appropriate techniques."},{"front":"Can a powerful device rescue weak evidence?","back":"Not reliably; persuasive style does not make unsupported reasoning sound."}]}]$json$::jsonb;
  v_item jsonb;
begin
  for v_item in select value from jsonb_array_elements(v_topics)
  loop
    insert into public.spark_subject_topics(
      subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata
    ) values (
      'english-a',
      v_item->>'id',
      v_item->>'section',
      v_item->>'title',
      v_item->>'intro',
      (v_item->>'order')::integer,
      true,
      jsonb_build_object(
        'syllabusObjectives',v_item->'objectives',
        'lesson',jsonb_build_object(
          'objectives',v_item->'objectives',
          'introduction',v_item->>'intro',
          'sections',v_item->'sections',
          'keyPoints',v_item->'keyPoints',
          'summary',v_item->>'summary',
          'flashcards',v_item->'cards'
        )
      )
    )
    on conflict(subject_id,topic_id) do update set
      section_id=excluded.section_id,
      title=excluded.title,
      description=excluded.description,
      sort_order=excluded.sort_order,
      enabled=true,
      metadata=excluded.metadata,
      updated_at=now();
  end loop;
end;
$body$;

update public.spark_subjects
set enabled=true,status='live',updated_at=now()
where id='english-a';

commit;
